const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
const initial={points:850,cart:{},bookings:[],quotes:[],vehicles:[{name:'Porsche 911 Carrera S',year:'2024',color:'Jet Black',image:'porsche.jpg'},{name:'BMW X7',year:'2025',color:'Alpine White',image:'ceramic.jpg'}],selectedVehicle:0,redemptions:[],messages:[],orders:[],profile:{name:'Marco',email:'',address:'Miami Shores, FL'},enrolled:false,notifications:{appointments:true,promotions:false}};
let state;try{state={...structuredClone(initial),...JSON.parse(localStorage.getItem('soflo-demo-v1')||'null')}}catch{state=structuredClone(initial)}
const save=()=>{try{localStorage.setItem('soflo-demo-v1',JSON.stringify(state))}catch{toast('Browser storage unavailable. This session still works.')}};
// Normalize old prototype sessions before rendering any screen.
for(const key of ['cart','profile','notifications'])if(!state[key]||typeof state[key]!=='object'||Array.isArray(state[key]))state[key]=structuredClone(initial[key]);
for(const key of ['bookings','quotes','vehicles','redemptions','messages','orders'])if(!Array.isArray(state[key]))state[key]=structuredClone(initial[key]);
if(!state.vehicles.length)state.vehicles=structuredClone(initial.vehicles);
for(const key of ['name','email','address'])if(typeof state.profile[key]!=='string')state.profile[key]=initial.profile[key];
if(!state.profile.name.trim())state.profile.name=initial.profile.name;
if(!Number.isFinite(state.points)||state.points<0)state.points=850;
const services=[{id:'reset',name:'Detail Reset',category:'Detailing',tag:'Refresh · Rejuvenate · Protect',description:'A complete interior and exterior refresh to bring your vehicle back to a clean baseline.',image:'detail.jpg',duration:'Vehicle-dependent',includes:['Careful exterior hand wash','Wheels and tires cleaned and dressed','Interior vacuum and surface cleaning','Glass cleaned inside and out'],book:true},{id:'clay',name:'Clay & Protect',category:'Detailing',tag:'Decontaminate · Smooth · Protect',description:'Remove bonded contamination and restore a smooth finish with short-term sealant protection.',image:'hero.jpg',duration:'Vehicle-dependent',includes:['Exterior hand wash','Iron decontamination and clay treatment','Paint sealant application','Wheels, tires and exterior glass'],book:true},{id:'interior',name:'Interior Renewal',category:'Detailing',tag:'Deep Clean · Refresh · Restore',description:'A deeper clean for interior surfaces, fabric and carpets, with scope tailored to condition.',image:'interior.jpg',duration:'Condition-dependent',includes:['Thorough vacuum','Steam cleaning where appropriate','Fabric and carpet extraction as needed','Interior surfaces and glass'],book:true},{id:'ceramic',name:'Ceramic Coating',category:'Protection',tag:'Gloss that goes further',description:'Explore FEYNLAB protection packages with preparation matched to your paint and your goals.',image:'ceramic.jpg',duration:'Inspection required',includes:['Paint inspection and preparation plan','Package-specific paint refinement','Ceramic protection application','Care guidance and maintenance requirements'],book:false},{id:'correction',name:'Paint Correction',category:'Protection',tag:'Restore clarity. Refine the finish.',description:'A tailored polishing plan to improve swirls and imperfections while respecting your clear coat.',image:'correction.jpg',duration:'Inspection required',includes:['Paint condition assessment','Test spot and realistic expectations','Selected enhancement or correction process','Recommended protection options'],book:false},{id:'ppf',name:'Paint Protection Film',category:'Protection',tag:'Protect what drives you',description:'Choose targeted or broader film coverage for vulnerable painted surfaces.',image:'ppf.jpg',duration:'Inspection required',includes:['Coverage and finish consultation','Vehicle-specific installation plan','Film care instructions','Post-installation checkup'],book:false},{id:'tint',name:'Ceramic Window Tint',category:'Protection',tag:'Comfort. Privacy. Clarity.',description:'Discuss ceramic film options, coverage and shade selection for your vehicle.',image:'hero.jpg',duration:'Quote required',includes:['Vehicle and glass assessment','Coverage and shade selection','Professional installation plan','Film aftercare guidance'],book:false}];
const products=[{id:'wash',name:'Wash Shampoo',brand:'PAICAR',category:'Wash',price:16.99,color:'#2fb3fa',desc:'A placeholder for your retail wash collection. Final product names, sizes and directions will come from the supplier.'},{id:'tire',name:'Tire Dressing',brand:'PAICAR',category:'Wheels',price:18.99,color:'#e11184',desc:'A placeholder for your tire care collection. Exact finish, application and compatibility will be confirmed before launch.'},{id:'interior-cleaner',name:'Interior Cleaner',brand:'PAICAR',category:'Interior',price:16.99,color:'#525dc9',desc:'An example interior care product listing for testing the shop experience.'},{id:'ceramic-care',name:'Coating Care Wash',brand:'FEYNLAB',category:'Wash',price:24.99,color:'#2fb3fa',desc:'An illustrative coating-care listing. This is not a verified supplier SKU.'},{id:'topper',name:'Gloss Enhancement',brand:'FEYNLAB',category:'Protection',price:39.99,color:'#e11184',desc:'An illustrative gloss-care listing. Final availability and product information require supplier confirmation.'},{id:'towel',name:'Microfiber Care Kit',brand:'SoFlo Essentials',category:'Accessories',price:29.99,color:'#697c89',desc:'A sample care kit to explore bundles and accessories in the app.'}];
const nav=[['home','Home','home'],['services','Book a service','calendar'],['garage','My garage','car'],['shop','Product shop','bag'],['rewards','Suds rewards','star'],['appointments','Appointments','clock'],['messages','Messages','chat'],['account','My account','user']];
let shopFilter='All',serviceFilter='All',offerIndex=0,bookingDraft={service:'reset',step:1,addons:[],date:'',time:'9:00 AM',address:state.profile.address},toastTimer;
function go(page){location.hash=page}
function route(){return (location.hash.slice(1)||'home').split('/')[0]}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function button(label,action,style='',attrs=''){return `<button type="button" class="btn ${style}" data-action="${action}" ${attrs}>${label}</button>`}
function title(heading,sub='',extra=''){return `<div class="title-row"><div><h1>${heading}</h1>${sub?`<p>${sub}</p>`:''}</div>${extra}</div>`}
function panelTitle(label,link,action){return `<div class="section-head"><h2>${label}</h2>${link?`<button class="text-btn" data-action="${action}">${link} ${icon('arrow')}</button>`:''}</div>`}
function bottle(p){return `<div class="product-visual" style="--bottle-color:${p.color}"><div class="bottle"><div class="bottle-label">${esc(p.brand)}<br><br>DEMO<br>${esc(p.category)}</div></div></div>`}
function card(s){return `<button class="service-card" data-action="service:${s.id}"><img src="assets/${s.image}" alt="SoFlo Suds ${s.name.toLowerCase()} work" loading="lazy"><div class="info"><h3>${s.name}</h3><p>${s.tag}</p><span class="small blue">${s.book?'Explore service':'Request a quote'}</span><span class="arrow">${icon('arrow')}</span></div></button>`}
function shell(){const current=route();const active=current==='booking'?'services':current==='product'||current==='cart'?'shop':current;$('#sidebar').innerHTML=`<a href="#home" aria-label="SoFlo Suds home"><img class="logo" src="assets/logo.webp" alt="SoFlo Suds"></a><span class="eyebrow" style="padding:0 15px">Your vehicle. Elevated.</span><div class="menu">${nav.map(([id,label,i])=>`<a href="#${id}" class="nav-item ${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('')}</div><div class="sidebar-bottom"><button class="nav-item" data-action="go:owner">${icon('grid')}Owner preview</button><div class="row" style="padding:16px"><div class="avatar">${esc(state.profile.name.slice(0,1))}A</div><div><strong>${esc(state.profile.name)}</strong><div class="small muted">SoFlo member · Demo</div></div></div></div>`;
const count=Object.values(state.cart).reduce((a,b)=>a+b,0);$('#header').innerHTML=`<a href="#home"><img class="logo" src="assets/logo.webp" alt="SoFlo Suds home"></a><div class="header-location">${icon('pin')}<div><div class="small muted">YOUR SERVICE AREA</div><div>Miami-Dade & Broward</div></div></div><div class="header-right"><span class="demo-tag">DEMO MODE</span><button class="icon-btn" data-action="go:notifications" aria-label="Notifications">${icon('bell')}<span class="badge">3</span></button><button class="icon-btn" data-action="go:cart" aria-label="Cart, ${count} items">${icon('bag')}${count?`<span class="badge">${count}</span>`:''}</button><a href="#account" class="avatar" aria-label="Account">${esc(state.profile.name.slice(0,1))}A</a></div>`;
$('#bottom-nav').innerHTML=[['home','Home','home'],['services','Book','calendar'],['garage','Garage','car'],['shop','Shop','bag'],['account','Account','user']].map(([id,label,i])=>`<a href="#${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('')}
const offers=[{eyebrow:'THE PROTECTION EVENT',title:'A better finish.<br>A stronger shield.',text:'Explore ceramic protection for the road ahead. Sample offer: $100 off an eligible package.',image:'hero.jpg',cta:'Explore ceramic',action:'service:ceramic'},{eyebrow:'YOUR NEXT RESET',title:'Fresh inside.<br>Flawless outside.',text:'Bring the clean-car feeling back. Sample offer: $25 off a Detail Reset.',image:'detail.jpg',cta:'Book a reset',action:'service:reset'},{eyebrow:'CARE THAT CONTINUES',title:'Keep the finish.<br>Keep the feeling.',text:'A regular maintenance routine built around your vehicle and your schedule.',image:'ceramic.jpg',cta:'Explore membership',action:'go:membership'}];
function offerHero(){const o=offers[offerIndex];return `<div class="hero"><img src="assets/${o.image}" alt="Luxury vehicle cared for by SoFlo Suds"><div class="hero-content"><span class="pill">${o.eyebrow}</span><h2>${o.title}</h2><p>${o.text}</p>${button(o.cta+' '+icon('arrow'),o.action)}<div class="dots">${offers.map((_,i)=>`<button class="dot ${i===offerIndex?'on':''}" aria-label="Promotion ${i+1}" aria-pressed="${i===offerIndex}" data-action="offer:${i}"></button>`).join('')}</div></div></div>`}
function home(){return title(`Good to see you, ${esc(state.profile.name)}.`,`Exceptional care. Right where you are.`)+`<div class="hero-layout">${offerHero()}<div class="stack"><div class="panel reward-mini"><div class="row between"><span class="eyebrow">Suds rewards</span>${icon('star')}</div><div class="row" style="margin-top:12px"><strong class="reward-num">${state.points.toLocaleString()}</strong><span class="muted small">POINTS</span></div><div class="progress"><span style="width:${Math.min(state.points/10,100)}%"></span></div><div class="small muted">${Math.max(1000-state.points,0)} points to a 1,000-point reward</div><button class="text-btn" data-action="go:rewards">Explore your rewards ${icon('arrow')}</button></div><div class="panel appointment-mini"><div class="row"><div class="icon-tile">${icon('calendar')}</div><div><div class="small muted">YOUR NEXT SERVICE</div><h3>${state.bookings.length?esc(state.bookings.at(-1).service):'Keep it looking its best'}</h3></div></div><p class="small muted" style="margin:12px 0">${state.bookings.length?esc(state.bookings.at(-1).date)+' · '+esc(state.bookings.at(-1).time):'Choose your next detail or explore regular maintenance.'}</p><button class="text-btn" data-action="go:${state.bookings.length?'appointments':'services'}">${state.bookings.length?'View appointment':'Find your service'} ${icon('arrow')}</button></div></div></div>${panelTitle('Made for your vehicle','All services','go:services')}<div class="service-grid">${[services[0],services[3],services[5]].map(card).join('')}</div><div class="two-col gap"><div class="banner"><div><span class="eyebrow">GOOD CARE. SHARED.</span><h3 style="margin-top:7px">Give $25. Get $25.</h3><p>A proposed reward for a great introduction.</p></div>${button(icon('arrow'),'go:referrals','outline','aria-label="Explore referrals"')}</div><div class="banner blue-banner"><div><span class="eyebrow">THE MAINTENANCE CLUB</span><h3 style="margin-top:7px">Always ready for the road.</h3><p>Weekly, biweekly or every three weeks.</p></div>${button(icon('arrow'),'go:membership','outline','aria-label="Explore maintenance"')}</div></div>${panelTitle('Your SoFlo shortcuts')}<div class="three-col">${[['offers','Offers & gift cards','gift'],['messages','Talk to the team','chat'],['shop','Build your care kit','bag']].map(([p,t,i])=>`<button class="panel list-button row" data-action="go:${p}"><div class="icon-tile">${icon(i)}</div><h3 class="grow">${t}</h3>${icon('chevron')}</button>`).join('')}</div>`}
function servicePage(){return title('The right care. Every time.','From a fresh start to long-term protection.')+`<div class="chips">${['All','Detailing','Protection'].map(x=>`<button class="chip ${serviceFilter===x?'active':''}" data-action="service-filter:${x}">${x}</button>`).join('')}</div><div class="service-grid">${services.filter(x=>serviceFilter==='All'||x.category===serviceFilter).map(card).join('')}</div><div class="banner blue-banner gap"><div><h3>Not sure where to start?</h3><p>Show us your vehicle. We’ll help you choose the right approach.</p></div>${button('Ask the team','go:messages','outline')}</div><p class="local-note">Pricing and duration vary by vehicle size and condition. All appointments shown here are simulated.</p>`}
function serviceModal(id){const s=services.find(s=>s.id===id);if(!s)return;modal(s.name,`<img class="vehicle-img" style="height:200px;margin-bottom:18px" src="assets/${s.image}" alt="${esc(s.name)}"><span class="eyebrow">${s.tag}</span><p style="margin-top:12px">${s.description}</p><div class="stack">${s.includes.map(t=>`<div class="row small">${icon('check')}<span>${t}</span></div>`).join('')}</div><div class="notice">Pricing varies by vehicle size & condition. ${s.duration}. This prototype does not display a binding quote.</div>${button(s.book?'Build my booking':'Request a personal quote',`${s.book?'start-booking':'quote'}:${s.id}`,'full')}`)}
function currentVehicle(){return state.vehicles[state.selectedVehicle]||state.vehicles[0]}
function booking(){const s=services.find(x=>x.id===bookingDraft.service)||services[0];const v=currentVehicle();const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);const minDate=tomorrow.toLocaleDateString('en-CA');let content='';if(bookingDraft.step===1){content=`<h2>Your vehicle & extras</h2><div class="field gap"><label for="booking-vehicle">Choose your vehicle</label><select id="booking-vehicle" name="vehicle">${state.vehicles.map((v,i)=>`<option value="${i}" ${i===state.selectedVehicle?'selected':''}>${v.year} ${esc(v.name)}</option>`).join('')}</select></div><div class="field"><label for="service-choice">Service</label><select id="service-choice">${services.filter(x=>x.book).map(x=>`<option value="${x.id}" ${s.id===x.id?'selected':''}>${x.name}</option>`).join('')}</select></div><h3>Make it yours</h3>${['Engine Bay Detail','Glass Protection','Leather Protection'].map((x,i)=>`<div class="check-row"><input id="addon-${i}" type="checkbox" value="${x}" ${bookingDraft.addons.includes(x)?'checked':''}><label for="addon-${i}">${x}<div class="small muted">Price confirmed with your quote</div></label></div>`).join('')}<div class="field gap"><label for="condition">Condition or special requests</label><textarea id="condition" placeholder="Pet hair, stains, access instructions…">${esc(bookingDraft.notes||'')}</textarea></div>${button('Choose a time '+icon('arrow'),'booking-next','full')}`}
if(bookingDraft.step===2){content=`<h2>When & where?</h2><p class="muted small gap">Choose a preferred slot to test the experience. Availability is illustrative.</p><div class="field gap"><label for="booking-date">Preferred service date</label><input id="booking-date" type="date" min="${minDate}" value="${esc(bookingDraft.date)}" required></div><div class="field"><label for="booking-time">Preferred arrival window</label><select id="booking-time">${['9:00 AM','12:00 PM','3:00 PM'].map(t=>`<option ${bookingDraft.time===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="booking-address">Service address or area</label><input id="booking-address" value="${esc(bookingDraft.address)}" placeholder="Your home or office in Miami-Dade or Broward" required></div><div class="notice">Mobile service eligibility depends on the selected work, location and access. Final arrangements require confirmation.</div>${button('Review my request '+icon('arrow'),'booking-next','full')}`}
if(bookingDraft.step===3){content=`<h2>Looking good. One last check.</h2><div class="summary-row"><span class="muted">Vehicle</span><span>${esc(v.year+' '+v.name)}</span></div><div class="summary-row"><span class="muted">Service</span><span>${s.name}</span></div><div class="summary-row"><span class="muted">Date</span><span>${esc(bookingDraft.date)} · ${esc(bookingDraft.time)}</span></div><div class="summary-row"><span class="muted">Location</span><span>${esc(bookingDraft.address)}</span></div><div class="summary-row"><span class="muted">Extras</span><span>${esc(bookingDraft.addons.join(', ')||'None selected')}</span></div><div class="summary-row"><span class="muted">Price</span><span>Quote required</span></div><div class="notice">This creates a demo request in this browser only. No appointment is sent, booked or charged.</div>${button('Create demo booking '+icon('check'),'booking-confirm','full')}`}
return `<button class="back" data-action="${bookingDraft.step>1?'booking-back':'go:services'}">${icon('back')} ${bookingDraft.step>1?'Previous step':'Services'}</button>${title('Your next clean starts here.','Build your appointment request.')}<div class="booking-steps">${['Vehicle & extras','Date & location','Review'].map((t,i)=>`<div class="booking-step ${bookingDraft.step>=i+1?'active':''}">${i+1}. ${t}</div>`).join('')}</div><div class="two-col"><div class="panel">${content}</div><div class="stack"><img class="vehicle-img" src="assets/${s.image}" alt="${s.name}"><div class="panel"><span class="eyebrow">YOUR SELECTED SERVICE</span><h2 style="margin:10px 0">${s.name}</h2><p class="muted small">${s.description}</p><ul class="membership-benefits">${s.includes.map(t=>`<li>${icon('check')}${t}</li>`).join('')}</ul></div></div></div>`}
function garage(){const v=currentVehicle();return title('Your garage. Protected.','Every vehicle. Every service. One place.',button(icon('plus')+' Add vehicle','add-vehicle','secondary sm'))+`<div class="chips">${state.vehicles.map((v,i)=>`<button class="chip ${state.selectedVehicle===i?'active':''}" data-action="vehicle:${i}">${esc(v.name)}</button>`).join('')}</div><div class="two-col"><div><img class="vehicle-img" src="assets/${v.image}" alt="Illustrative SoFlo Suds vehicle photo"><h2 style="margin:20px 0 5px">${esc(v.year+' '+v.name)}</h2><p class="muted">${esc(v.color)} · Demo vehicle record</p><div class="notice">Photos and installed protection are sample records for exploring the app.</div>${button('Book for this vehicle '+icon('arrow'),'go:services','full')}</div><div class="panel"><h2>Protection passport</h2>${[['Ceramic coating','Paint & body protection','Coating care matters'],['Paint protection film','Full front coverage','Inspection recommended'],['Ceramic window tint','Sides & rear','Follow film care guidance']].map(([a,b,c])=>`<button class="list-row list-button" data-action="passport:${a}"><div class="icon-tile">${icon('shield')}</div><div class="grow"><h3>${a}</h3><p>${b}</p><span class="small blue">${c}</span></div>${icon('chevron')}</button>`).join('')}${[['history','Service history','document'],['care','Care instructions','shield'],['membership','Maintenance plan','calendar']].map(([p,t,i])=>`<button class="list-row list-button" data-action="go:${p}">${icon(i)}<span class="grow">${t}</span>${icon('chevron')}</button>`).join('')}</div></div>`}
function membership(){return title('Clean isn’t a one-time thing.','Meet the SoFlo Suds Maintenance Club.')+`<div class="two-col"><div class="digital-card"><div class="row between"><img class="logo" src="assets/logo.webp" alt="SoFlo Suds"><span class="pill blue-pill">${state.enrolled?'Demo enrollment':'Maintenance club'}</span></div><h2>Always cared for.<br>Always ready.</h2><p class="muted">A consistent routine for a finish you love.</p><div class="row between gap"><div><div class="small muted">MEMBER</div><div>${esc(state.profile.name)}</div></div><div><div class="small muted">YOUR VEHICLE</div><div>${esc(currentVehicle().name)}</div></div></div></div><div class="panel"><h2>Choose your rhythm</h2><div class="field gap"><label for="cadence">Preferred maintenance frequency</label><select id="cadence"><option>Every 3 weeks</option><option>Every 2 weeks</option><option>Weekly</option></select></div><ul class="membership-benefits"><li>${icon('check')}Regular vehicle care</li><li>${icon('check')}Vehicle-specific maintenance pricing</li><li>${icon('check')}Reminders before your next service</li><li>${icon('check')}Service records in your garage</li></ul><div class="notice">A Detail Reset is required before enrollment. Missed maintenance cadence may require another Reset. Pricing and eligibility are confirmed individually.</div>${button(state.enrolled?'Update demo preference':'Try demo enrollment','enroll','full')}</div></div>`}
function rewards(){return title('Good care deserves more.','Your proposed Suds Rewards experience.')+`<div class="digital-card"><span class="eyebrow">YOUR AVAILABLE POINTS</span><div class="reward-num" style="margin:12px 0">${state.points.toLocaleString()} <span class="small muted">POINTS</span></div><div class="progress"><span style="width:${Math.min(state.points/10,100)}%"></span></div><div class="small muted">${Math.max(1000-state.points,0)} points to a 1,000-point reward</div></div>${panelTitle('A little something for you')}<div class="two-col">${[['credit','$25 service credit','Put your points toward a future eligible service.'],['addon','Complimentary add-on','Choose from eligible add-ons at your next visit.']].map(([id,t,d])=>`<div class="panel reward-card"><div class="reward-symbol">${icon(id==='credit'?'gift':'spark')}</div><h2>${t}</h2><p class="muted small">${d}</p><strong class="blue">1,000 points</strong>${button(state.points>=1000?'Redeem demo reward':'1,000 points needed','redeem:'+id,'outline',state.points<1000?'disabled':'')}</div>`).join('')}</div><div class="banner blue-banner gap"><div><h3>Test the reward experience</h3><p>Add 200 demo points to try redeeming a reward.</p></div>${button('+200 points','demo-points','secondary sm')}</div>${panelTitle('Your reward activity')}<div class="panel">${state.redemptions.map(x=>`<div class="summary-row"><span>${esc(x)}</span><span class="pink">−1,000</span></div>`).join('')}<div class="summary-row"><span>Welcome demo balance</span><span class="blue">+850</span></div></div><p class="local-note">Illustrative rewards only. Earning rules, exclusions and redemption terms are not finalized.</p>`}
function shop(){const query=(new URLSearchParams(location.hash.split('?')[1]||'')).get('q')||'';return title('Bring the SoFlo feeling home.','Build a better routine between details.',button(icon('bag')+' Cart','go:cart','secondary sm'))+`<div class="banner blue-banner"><div><span class="eyebrow">THE CARE COLLECTION</span><h2 style="margin:9px 0">Your finish. Your care kit.</h2><p>Explore sample PAICAR, FEYNLAB and accessory collections.</p></div><div class="icon-tile">${icon('bag')}</div></div><div class="notice">Sample catalog, bottle artwork and prices. Supplier SKUs, stock and product directions are not connected.</div><form id="search-form" class="row"><label class="sr-only" for="product-search">Search products</label><input class="search" id="product-search" name="q" placeholder="Find your next care essential" value="${esc(query)}"><button class="btn secondary" type="submit">Search</button></form><div class="chips">${['All','PAICAR','FEYNLAB','Accessories'].map(t=>`<button class="chip ${shopFilter===t?'active':''}" data-action="shop-filter:${t}">${t}</button>`).join('')}</div><div class="product-grid">${products.filter(p=>(shopFilter==='All'||p.brand===shopFilter||p.category===shopFilter)&&(p.name+' '+p.brand).toLowerCase().includes(query.toLowerCase())).map(p=>`<div class="product"><button class="list-button" data-action="product:${p.id}" style="padding:0" aria-label="View ${p.name}">${bottle(p)}</button><div class="product-info"><span class="brand">${p.brand}</span><h3>${p.name}</h3><span class="small muted">Sample product · Demo price</span><div class="row between"><strong>${money(p.price)}</strong>${button(icon('plus'),'cart-add:'+p.id,'secondary','aria-label="Add '+p.name+' to cart"')}</div></div></div>`).join('')||'<p class="muted">No sample products match your search.</p>'}</div>`}
function productModal(id){const p=products.find(p=>p.id===id);if(!p)return;modal(p.name,`${bottle(p)}<p class="eyebrow" style="margin-top:20px">${p.brand}</p><h2 style="margin-bottom:12px">${money(p.price)} <span class="small muted">demo price</span></h2><p>${p.desc}</p><div class="field"><label for="size">Sample size</label><select id="size"><option>Standard bottle · Demo variant</option></select></div><div class="notice">Illustrative listing. No verified formulation, dilution or compatibility guidance is provided.</div>${button('Add to demo cart '+icon('bag'),'cart-add:'+p.id,'full')}`)}
function cart(){const items=products.filter(p=>state.cart[p.id]>0),sum=items.reduce((a,p)=>a+p.price*state.cart[p.id],0);return title('Your care kit.','Review your sample order before checkout.')+(items.length?`<div class="two-col"><div class="panel">${items.map(p=>`<div class="list-row"><div class="icon-tile">${icon('bag')}</div><div class="grow"><h3>${p.name}</h3><p>${p.brand} · ${money(p.price)} each</p><div class="count-control" style="margin-top:10px"><button data-action="cart-minus:${p.id}" aria-label="Decrease ${p.name} quantity">−</button><span>${state.cart[p.id]}</span><button data-action="cart-add:${p.id}" aria-label="Increase ${p.name} quantity">+</button></div></div><strong>${money(p.price*state.cart[p.id])}</strong></div>`).join('')}</div><div class="panel"><h2>Order summary</h2><div class="summary-row"><span>Sample subtotal</span><span>${money(sum)}</span></div><div class="summary-row"><span>Delivery / tax</span><span>Not calculated</span></div><div class="field gap"><label for="fulfillment">Demo fulfillment preference</label><select id="fulfillment"><option>Local pickup</option><option>Delivery with a service</option><option>Shipping</option></select></div><div class="notice">No payment is collected. Create a sample order to test the confirmation experience.</div>${button('Place demo order','order','full')}</div></div>`:`<div class="panel empty">${icon('bag')}<h2>A fresh start for your cart.</h2><p>Explore the sample care collection.</p>${button('Browse products','go:shop')}</div>`)}
function appointments(){return title('Your next clean, organized.','Appointment requests created in this demo.')+(state.bookings.length?`<div class="stack">${[...state.bookings].reverse().map((b,idx)=>`<div class="panel"><div class="row between wrap"><div><span class="pill blue-pill">${esc(b.status)}</span><h2 style="margin:12px 0">${esc(b.service)}</h2><p class="muted small">${esc(b.vehicle)}</p></div><div class="icon-tile">${icon('calendar')}</div></div><div class="row wrap gap"><span>${icon('calendar')} ${esc(b.date)}</span><span>${icon('clock')} ${esc(b.time)}</span><span>${icon('pin')} ${esc(b.address)}</span></div><div class="status-line">${['Requested','Confirmed','In progress','Complete'].map((t,i)=>`<div class="status-point ${i===0?'done':''}"><span>${i===0?icon('check'):''}</span>${t}</div>`).join('')}</div><div class="row wrap gap">${button('Reschedule','reschedule:'+b.id,'secondary sm')}${button('Message team','go:messages','outline sm')}${button('Cancel request','cancel:'+b.id,'outline sm')}</div></div>`).join('')}</div>`:`<div class="panel empty">${icon('calendar')}<h2>Your next visit starts here.</h2><p>Create a demo booking to see the appointment timeline.</p>${button('Explore services','go:services')}</div>`)}
function referrals(){return title('Great care gets passed around.','Introduce a friend to the SoFlo Suds experience.')+`<div class="two-col"><div class="hero"><img src="assets/hero.jpg" alt="SoFlo Suds luxury car detailing"><div class="hero-content"><span class="eyebrow">FRIENDS OF SOFLO</span><h2>Give $25.<br>Get $25.</h2><p>A proposed reward after your friend completes a qualifying first service.</p></div></div><div class="panel"><h2>Your personal invitation</h2><p class="muted small gap">Share your demo code with a friend.</p><div class="digital-card gap"><div class="eyebrow">YOUR DEMO CODE</div><h2 style="margin:12px 0">SOFLOMARCO</h2></div><div class="row wrap gap">${button(icon('copy')+' Copy code','copy-code','full')}${button('Preview invitation','referral-preview','outline full')}</div><p class="local-note">Proposed program. Credits, qualifying purchases and exclusions require final terms. Copying the code does not send an invitation.</p></div></div>`}
function offersPage(){return title('More reasons to love your ride.','Promotions, thoughtful gifts and member perks.')+`<div class="two-col">${offers.slice(0,2).map((o,i)=>`<div class="hero"><img src="assets/${o.image}" alt="SoFlo Suds service promotion"><div class="hero-content"><span class="pill">ILLUSTRATIVE OFFER</span><h2>${i?'$25 off<br>Detail Reset':'$100 off<br>Ceramic'}</h2><p>Sample offer for an eligible service. Final terms and availability to be confirmed.</p>${button('Explore offer',o.action)}</div></div>`).join('')}</div><div class="banner gap"><div><span class="eyebrow">GIVE THE CLEAN-CAR FEELING</span><h2 style="margin-top:10px">A gift that shines.</h2><p>Explore a digital gift card for someone who loves their vehicle.</p></div>${button('Try a gift card','gift')}</div>${panelTitle('The SoFlo community')}<div class="two-col"><div class="panel"><div class="icon-tile">${icon('people')}</div><h3 class="gap">Cars, coffee & good company.</h3><p class="muted small gap">A proposed member event series. No events are currently scheduled in this demo.</p>${button('Join demo interest list','event-interest','outline gap')}</div><div class="panel"><div class="icon-tile">${icon('gift')}</div><h3 class="gap">Member partner benefits</h3><p class="muted small gap">A future home for selected automotive and local partner offers.</p><span class="pill blue-pill" style="margin-top:20px">Concept · Coming later</span></div></div>`}
function messages(){return title('A real connection to your care.','Demo conversation · Messages are not sent to SoFlo Suds.')+`<div class="panel" style="max-width:760px"><div class="row"><div class="avatar">SS</div><div><h3>SoFlo Suds team</h3><div class="small muted">Appointments Only · Miami-Dade & Broward</div></div></div><div class="gap"><div class="message">Hi ${esc(state.profile.name)}, welcome to SoFlo Suds. Tell us about your vehicle and the finish you’re looking for.</div>${state.messages.map(t=>`<div class="message mine">${esc(t)}</div>`).join('')}</div><form id="chat-form" class="chat-form"><label class="sr-only" for="chat-text">Demo message</label><input class="search" id="chat-text" name="message" placeholder="Try typing a message…" maxlength="1000" required><button class="btn" type="submit" aria-label="Add demo message">${icon('send')}</button></form><p class="local-note">Messages stay in this browser. No team member receives them.</p></div>`}
function notifications(){return title('You’re in the loop.','Sample appointment, vehicle and reward updates.')+`<div class="panel">${[['calendar','Appointment reminders','See your upcoming service details in one place.','appointments'],['document','Your quotes','Review requested services and scope.','quotes'],['star','Rewards are waiting','Explore your points and proposed rewards.','rewards'],['shield','Keep your protection cared for','View your maintenance options.','membership'],['bag','Order updates','View your sample shop orders.','orders']].map(([i,t,d,p])=>`<button class="list-row list-button" data-action="go:${p}"><div class="icon-tile">${icon(i)}</div><div class="grow"><h3>${t}</h3><p>${d}</p></div>${icon('chevron')}</button>`).join('')}</div><div class="panel gap"><h2>Make notifications yours</h2>${[['appointments','Appointment & service updates'],['promotions','Offers & promotional messages']].map(([k,t])=>`<div class="check-row"><input id="notify-${k}" type="checkbox" data-setting="${k}" ${state.notifications[k]?'checked':''}><label for="notify-${k}">${t}</label></div>`).join('')}<p class="local-note">These are local preference controls. No push notification service is connected.</p></div>`}
function account(){return title('Your SoFlo, your way.','Manage your demo profile and explore every feature.')+`<div class="two-col"><div class="panel"><div class="row"><div class="avatar">${esc(state.profile.name[0]||'M')}A</div><div><h2>${esc(state.profile.name)}</h2><span class="small muted">Customer profile · Demo</span></div></div><form id="profile-form" class="gap"><div class="field"><label for="profile-name">First name</label><input id="profile-name" name="name" maxlength="40" value="${esc(state.profile.name)}" required></div><div class="field"><label for="profile-email">Email (optional)</label><input id="profile-email" name="email" type="email" value="${esc(state.profile.email)}" placeholder="For testing only"></div><div class="field"><label for="profile-address">Preferred service area</label><input id="profile-address" name="address" value="${esc(state.profile.address)}" required></div><button class="btn full" type="submit">Save demo profile</button></form><p class="local-note">Stored only in this browser. Use sample information while testing.</p></div><div class="panel">${[['rewards','Suds rewards','star'],['membership','Maintenance club','shield'],['appointments','Appointments','calendar'],['quotes','My quote requests','document'],['payments','Invoices & payments','card'],['orders','Shop orders','bag'],['offers','Offers, gifts & events','gift'],['referrals','Refer a friend','people'],['notifications','Notification preferences','bell'],['owner','Owner dashboard preview','grid']].map(([p,t,i])=>`<button class="list-row list-button" data-action="go:${p}">${icon(i)}<span class="grow">${t}</span>${icon('chevron')}</button>`).join('')}<button class="list-row list-button" data-action="reset-demo">${icon('settings')}<span class="grow">Reset all demo data</span>${icon('chevron')}</button></div></div>`}
function orders(){return title('Your orders.','Sample orders stored on this device.')+(state.orders.length?`<div class="stack">${[...state.orders].reverse().map(o=>`<div class="panel"><div class="row between"><h3>Demo order ${esc(o.id)}</h3><span class="pill blue-pill">${esc(o.fulfillment)}</span></div>${o.items.map(i=>`<div class="summary-row"><span>${esc(i.name)} × ${i.qty}</span><span>${money(i.price*i.qty)}</span></div>`).join('')}<div class="summary-row"><strong>Sample subtotal</strong><strong>${money(o.total)}</strong></div><p class="local-note">Not submitted or paid. Fulfillment is illustrative.</p></div>`).join('')}</div>`:`<div class="panel empty">${icon('bag')}<h2>Your care kit is waiting.</h2><p>Place a demo order to explore this screen.</p>${button('Shop the collection','go:shop')}</div>`)}
function quotes(){return title('Your protection plans.','Quote requests created in the prototype.')+(state.quotes.length?`<div class="stack">${state.quotes.map(q=>`<div class="panel"><div class="row between"><h2>${esc(q.service)}</h2><span class="pill blue-pill">Demo request</span></div><p class="muted gap">${esc(q.vehicle)}</p><p class="small muted">${esc(q.notes||'No additional notes.')}</p><div class="notice">Not sent to the business. A live quote and approval flow would connect here.</div>${button('Discuss this request','go:messages','outline')}</div>`).join('')}</div>`:`<div class="panel empty">${icon('document')}<h2>Start with your goals.</h2><p>Explore ceramic coating, paint correction, PPF or tint.</p>${button('Explore protection','go:services')}</div>`)}
function history(){return title('A record of great care.','Illustrative service history for '+esc(currentVehicle().name))+`<div class="panel">${[['Ceramic Coating & Preparation','Protection installation · Sample record'],['Maintenance Detail','Interior and exterior care · Sample record']].map(([t,d])=>`<button class="list-row list-button" data-action="history-record"><div class="icon-tile">${icon('document')}</div><div class="grow"><h3>${t}</h3><p>${d}</p></div>${icon('chevron')}</button>`).join('')}</div>`}
function care(){return title('Protect the finish you love.','General care pointers. Follow your installed product’s instructions.')+`<div class="two-col">${[['Wash with care','Use suitable wash products, clean tools and gentle techniques. Ask your installer for product-specific guidance.'],['Keep a consistent routine','Regular maintenance helps remove contamination and gives us a chance to assess the finish.'],['Check your documents','Curing times, maintenance requirements and warranty coverage vary by product and installation.'],['Ask before treating a mark','Send photos before trying abrasive or aggressive treatments on protected surfaces.']].map(([t,d])=>`<div class="panel"><div class="icon-tile">${icon('shield')}</div><h3 class="gap">${t}</h3><p class="muted small" style="margin-top:12px">${d}</p></div>`).join('')}</div><div class="gap">${button('Ask about my protection','go:messages','full')}</div>`}
function owner(){return title('Behind the finish.','Owner dashboard concept · Sample business data.',`<span class="pill blue-pill">Owner preview</span>`)+`<div class="stats-grid">${[['Demo requests',state.bookings.length],['Quote requests',state.quotes.length],['Sample orders',state.orders.length]].map(([t,n])=>`<div class="panel"><span class="small muted">${t}</span><div class="stat-value">${n}</div></div>`).join('')}</div>${panelTitle('Your business, connected')}<div class="three-col">${[['appointments','Calendar & dispatch','calendar'],['quotes','Quotes & approvals','document'],['payments','Invoices & payments','card'],['orders','Orders & fulfillment','bag'],['messages','Customer conversations','chat'],['membership','Maintenance management','shield'],['garage','Customer vehicles','car']].map(([p,t,i])=>`<button class="panel list-button stack" data-action="go:${p}"><div class="icon-tile">${icon(i)}</div><h3>${t}</h3><span class="small blue">Explore demo ${icon('arrow')}</span></button>`).join('')}</div><div class="notice">This is a layout preview using your local demo activity. There is no live CRM, scheduling, inventory, reporting or payment connection.</div>`}
const screens={payments,home,services:servicePage,booking,garage,membership,rewards,shop,cart,appointments,referrals,offers:offersPage,messages,notifications,account,orders,quotes,history,care,owner};
function payments(){return title('Simple, from quote to receipt.','An illustrative invoice and payment experience.')+`<div class="two-col"><div class="panel"><div class="row between"><h2>Detail Reset</h2><span class="pill ${state.demoPaid?'green':'blue-pill'}">${state.demoPaid?'Demo paid':'Sample invoice'}</span></div><p class="muted small gap">Demo invoice SS-1001 · ${esc(currentVehicle().name)}</p><div class="summary-row"><span>Sample service</span><span>$200.00</span></div><div class="summary-row"><span>Sample deposit</span><span>−$50.00</span></div><div class="summary-row"><strong>Demo balance</strong><strong>${state.demoPaid?'$0.00':'$150.00'}</strong></div><div class="notice">Illustrative amounts only. No payment processor is connected and no financial information is requested.</div>${button(state.demoPaid?'View demo receipt':'Simulate payment','payment-demo','full')}</div><div class="panel"><div class="icon-tile">${icon('card')}</div><h2 class="gap">Your payment history</h2><p class="muted small gap">A live connection would display deposits, invoices, receipts and outstanding balances from your service records.</p></div></div>`}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="payment-demo"]')){state.demoPaid=true;save();render();success('Demo payment complete.','Sample receipt SS-1001 · $150.00. No card was requested and no money was charged.','go:payments','View demo invoice')}});
function render(){shell();$('#main').innerHTML=(screens[route()]||home)();document.title=(nav.find(n=>n[0]===route())?.[1]||'SoFlo Suds')+' | SoFlo Suds';}
function modal(heading,content){$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="close-row"><h2 id="modal-title">${heading}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${content}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#overlay').querySelector('input,select,button')?.focus(),0)}
let lastFocus;
function close(){const returnTo=lastFocus;$('#overlay').innerHTML='';document.body.style.overflow='';if(returnTo?.isConnected)returnTo.focus()}
function quoteModal(id){const s=services.find(s=>s.id===id);close();modal('Let’s plan your '+s.name.toLowerCase(),`<form id="quote-form" data-service="${id}"><div class="field"><label for="quote-vehicle">Vehicle</label><select id="quote-vehicle" name="vehicle">${state.vehicles.map((v,i)=>`<option value="${i}" ${i===state.selectedVehicle?'selected':''}>${esc(v.year+' '+v.name)}</option>`).join('')}</select></div><div class="field"><label for="quote-notes">What would you like to achieve?</label><textarea id="quote-notes" name="notes" placeholder="Protection coverage, paint concerns, preferred finish…" required></textarea></div><label class="file-label" for="quote-photos">Add condition photos (optional)<input id="quote-photos" type="file" accept="image/*" multiple><span class="small">Preview only. Photos are not uploaded or saved.</span></label><div class="notice">Create a local demo request. Nothing is sent to SoFlo Suds.</div><button class="btn full" type="submit">Create demo quote request</button></form>`)}
function success(titleText,bodyText,action='go:home',label='Back to home'){modal(titleText,`<div class="empty" style="padding:15px 0"><div class="success-mark">${icon('check')}</div><h2>${titleText}</h2><p>${bodyText}</p>${button(label,action,'full')}</div>`)}
function bookingNext(){if(bookingDraft.step===1){state.selectedVehicle=Number($('#booking-vehicle').value);bookingDraft.service=$('#service-choice').value;bookingDraft.addons=[...document.querySelectorAll('[id^="addon-"]:checked')].map(x=>x.value);bookingDraft.notes=$('#condition').value;save()}else{const date=$('#booking-date'),address=$('#booking-address');if(!date.reportValidity()||!address.reportValidity())return;if(date.value<date.min){toast('Please choose a future service date.');return}bookingDraft.date=date.value;bookingDraft.time=$('#booking-time').value;bookingDraft.address=address.value.trim();if(!bookingDraft.address){toast('Please enter a service location.');return}}bookingDraft.step++;render();window.scrollTo(0,0)}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const [a,...parts]=el.dataset.action.split(':'),arg=parts.join(':');lastFocus=el;switch(a){case 'go':close();go(arg);break;case 'close':close();break;case 'offer':offerIndex=Number(arg);render();break;case 'service-filter':serviceFilter=arg;render();break;case 'shop-filter':shopFilter=arg;render();break;case 'service':serviceModal(arg);break;case 'start-booking':bookingDraft={...bookingDraft,service:arg,step:1};close();go('booking');break;case 'booking-next':bookingNext();break;case 'booking-back':bookingDraft.step=Math.max(1,bookingDraft.step-1);render();break;case 'booking-confirm':{const s=services.find(x=>x.id===bookingDraft.service);state.bookings.push({id:Date.now(),service:s.name,vehicle:currentVehicle().year+' '+currentVehicle().name,date:bookingDraft.date,time:bookingDraft.time,address:bookingDraft.address,status:'Demo requested',addons:bookingDraft.addons,notes:bookingDraft.notes});save();bookingDraft.step=1;go('appointments');success('Your demo request is ready.','Explore it in your appointments. No real appointment has been booked.','go:appointments','View appointments');break}case 'quote':quoteModal(arg);break;case 'vehicle':state.selectedVehicle=Number(arg);save();render();break;case 'add-vehicle':modal('Add a vehicle',`<form id="vehicle-form"><div class="field"><label for="vehicle-name">Make & model</label><input id="vehicle-name" name="name" placeholder="Mercedes-Benz GLE 350" maxlength="60" required></div><div class="two-col mobile-two"><div class="field"><label for="vehicle-year">Year</label><input id="vehicle-year" name="year" type="number" min="1900" max="2028" value="2026" required></div><div class="field"><label for="vehicle-color">Color</label><input id="vehicle-color" name="color" placeholder="Black" maxlength="40" required></div></div><button class="btn full" type="submit">Save demo vehicle</button></form>`);break;case 'passport':modal(arg,`<span class="pill blue-pill">Sample protection record</span><p class="gap">${esc(currentVehicle().year+' '+currentVehicle().name)}</p><div class="summary-row"><span>Coverage</span><span>Illustrative record</span></div><div class="summary-row"><span>Installed product</span><span>To be connected</span></div><div class="notice">Live installation dates, warranty documents, coverage and maintenance requirements will appear here when connected to service records.</div>${button('View care guidance','go:care','full')}`);break;case 'enroll':state.enrolled=true;state.cadence=$('#cadence').value;save();success('Preference saved.','Demo maintenance preference: '+esc(state.cadence)+'. Enrollment and pricing still require business confirmation.','go:membership','View membership');break;case 'demo-points':state.points+=200;save();render();toast('200 demo points added.');break;case 'redeem':if(state.points<1000)return;state.points-=1000;state.redemptions.unshift(arg==='credit'?'Demo $25 credit redeemed':'Demo add-on redeemed');save();render();success('Reward unlocked.','Your demo reward is recorded. It has no cash value and cannot be used for a real service.','go:rewards','View rewards');break;case 'product':productModal(arg);break;case 'cart-add':if(!products.some(p=>p.id===arg))return;state.cart[arg]=(state.cart[arg]||0)+1;save();shell();if(route()==='cart')render();toast('Added to your demo care kit.');break;case 'cart-minus':state.cart[arg]=Math.max(0,(state.cart[arg]||0)-1);save();render();break;case 'order':{const items=products.filter(p=>state.cart[p.id]>0).map(p=>({name:p.name,price:p.price,qty:state.cart[p.id]}));if(!items.length)return;state.orders.push({id:String(Date.now()).slice(-6),items,total:items.reduce((t,p)=>t+p.qty*p.price,0),fulfillment:$('#fulfillment').value});state.cart={};save();go('orders');success('Your sample order is ready.','No payment was collected and no order was sent.','go:orders','View sample order');break}case 'copy-code':try{await navigator.clipboard.writeText('SOFLOMARCO');toast('Demo code SOFLOMARCO copied.')}catch{modal('Your referral code','<h2>SOFLOMARCO</h2><p class="gap">Copy this demo code to try the referral experience.</p>')}break;case 'referral-preview':modal('Your invitation preview','<p>Great care deserves to be shared. Explore SoFlo Suds Auto Detailing & Ceramic Coating and use my demo code SOFLOMARCO.</p><div class="notice">Sample invitation only. No message has been sent.</div>');break;case 'gift':modal('Give the clean-car feeling.',`<form id="gift-form"><div class="digital-card"><img class="logo" src="assets/logo.webp" alt="SoFlo Suds"><h2>Gift card</h2></div><div class="field gap"><label for="gift-amount">Sample gift amount</label><select name="amount" id="gift-amount"><option value="50">$50</option><option value="100">$100</option><option value="250">$250</option></select></div><div class="field"><label for="gift-name">Recipient first name</label><input id="gift-name" name="name" required maxlength="50" placeholder="Who is the lucky one?"></div><div class="notice">Demo preview only. No purchase or delivery takes place.</div><button type="submit" class="btn full">Preview gift card</button></form>`);break;case 'event-interest':success('You’re on the demo list.','This previews the interest-list experience. No event registration or message has been sent.','go:offers','Back to offers');break;case 'reschedule':{const b=state.bookings.find(x=>x.id===Number(arg));if(!b)return;modal('Choose another date',`<form id="reschedule-form" data-id="${b.id}"><div class="field"><label for="new-date">Preferred date</label><input id="new-date" name="date" type="date" value="${esc(b.date)}" min="${new Date(Date.now()+86400000).toLocaleDateString('en-CA')}" required></div><div class="field"><label for="new-time">Arrival window</label><select id="new-time" name="time"><option>9:00 AM</option><option>12:00 PM</option><option>3:00 PM</option></select></div><button class="btn full" type="submit">Update demo request</button></form>`);break}case 'cancel':modal('Cancel this demo request?',`<p>This removes the appointment request from this browser’s demo data.</p>${button('Remove demo request','cancel-confirm:'+arg,'full')}`);break;case 'cancel-confirm':state.bookings=state.bookings.filter(x=>x.id!==Number(arg));save();close();render();toast('Demo request removed.');break;case 'history-record':modal('Service record preview','<p>Your completed service record would include its scope, date, photos, invoice and aftercare documents.</p><div class="notice">No live service record is connected.</div>'+button('View general care guidance','go:care','full'));break;case 'reset-demo':modal('Start fresh?',`<p>Clear this browser’s sample bookings, cart, vehicles, messages, profile and rewards.</p>${button('Reset demo data','reset-confirm','full')}`);break;case 'reset-confirm':state=structuredClone(initial);save();close();go('home');render();toast('Demo reset.');break;}});
document.addEventListener('submit',e=>{const f=e.target;if(!['profile-form','vehicle-form','quote-form','chat-form','search-form','gift-form','reschedule-form'].includes(f.id))return;e.preventDefault();const d=new FormData(f);switch(f.id){case 'profile-form':{const name=String(d.get('name')).trim(),address=String(d.get('address')).trim();if(!name||!address){toast('Please enter a name and service area.');return}state.profile={name,email:String(d.get('email')).trim(),address};bookingDraft.address=address;save();render();toast('Demo profile saved.');break}case 'vehicle-form':{const name=String(d.get('name')).trim(),color=String(d.get('color')).trim();if(!name||!color)return;state.vehicles.push({name,color,year:String(d.get('year')),image:'hero.jpg'});state.selectedVehicle=state.vehicles.length-1;save();close();render();toast('Vehicle added to your demo garage.');break}case 'quote-form':{const notes=String(d.get('notes')).trim();if(!notes){toast('Tell us a little about your goals.');return}const s=services.find(s=>s.id===f.dataset.service),v=state.vehicles[Number(d.get('vehicle'))];state.quotes.push({service:s.name,vehicle:v.year+' '+v.name,notes});save();close();go('quotes');success('Your demo quote request is ready.','It is stored in this browser only. Your photos were not uploaded.','go:quotes','View requests');break}case 'chat-form':{const t=String(d.get('message')).trim();if(t){state.messages.push(t);save();render();toast('Demo message saved locally.')}break}case 'search-form':location.hash='shop?q='+encodeURIComponent(String(d.get('q')).trim());break;case 'gift-form':{const name=esc(d.get('name')),amount=Number(d.get('amount'));modal('Gift card preview',`<div class="digital-card"><img class="logo" src="assets/logo.webp" alt="SoFlo Suds"><h2>${money(amount)}</h2><p>For ${name}</p></div><div class="notice">Preview only. No gift card has been issued, paid for or sent.</div>${button('Back to gifts','go:offers','full')}`);break}case 'reschedule-form':{const b=state.bookings.find(x=>x.id===Number(f.dataset.id));if(b){b.date=String(d.get('date'));b.time=String(d.get('time'));save();close();render();toast('Demo appointment updated.')}break}}});
document.addEventListener('change',e=>{if(e.target.dataset.setting){state.notifications[e.target.dataset.setting]=e.target.checked;save();toast('Demo preference saved.')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&$('#overlay').firstChild){const focusable=[...$('#overlay').querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
$('#overlay').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))close()});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
